insert into public.checklist_itens (id, tipo, modulo, secao, ordem, pergunta, ativo) values
  ('onb01', 'vme-onibus-csp', 'base', 'Visibilidade e Iluminação', 1, 'Possui para-brisa com vidro laminado e sem trincas?', true),
  ('onb02', 'vme-onibus-csp', 'base', 'Visibilidade e Iluminação', 2, 'O limpador e o lavador do para-brisa estão em condições de funcionamento?', true),
  ('onb03', 'vme-onibus-csp', 'base', 'Visibilidade e Iluminação', 3, 'Possui retrovisores interno e os externos em ambos os lados íntegros?', true),
  ('onb04', 'vme-onibus-csp', 'base', 'Visibilidade e Iluminação', 4, 'Possui quebra-sol em condições de funcionamento?', true),
  ('onb05', 'vme-onibus-csp', 'base', 'Visibilidade e Iluminação', 5, 'Possui lanternas, faróis, luz (de ré, freio, placa, de alerta, setas e break-light) conformes?', true),
  ('onb06', 'vme-onibus-csp', 'base', 'Sistemas de Frenagem e Rodagem', 6, 'Possui sistema antitravamento de freios (ABS)?', true),
  ('onb07', 'vme-onibus-csp', 'base', 'Sistemas de Frenagem e Rodagem', 7, 'Possui freios de estacionamento e de serviço, com comandos independentes? E estão eficazes?', true),
  ('onb08', 'vme-onibus-csp', 'base', 'Sistemas de Frenagem e Rodagem', 8, 'Possui pneus que ofereçam condições de segurança, conforme orientação do fabricante, dentro do TWI?', true),
  ('onb09', 'vme-onibus-csp', 'base', 'Equipamentos de Segurança, Emergência e Sinalização', 9, 'Todos os assentos possuem cinto de segurança em perfeito estado?', true),
  ('onb10', 'vme-onibus-csp', 'base', 'Equipamentos de Segurança, Emergência e Sinalização', 10, 'Possui extintor de incêndio, lacrado e dentro da validade?', true),
  ('onb11', 'vme-onibus-csp', 'base', 'Equipamentos de Segurança, Emergência e Sinalização', 11, 'Possui dispositivos para sinalização (triângulos refletivos)?', true),
  ('onb12', 'vme-onibus-csp', 'base', 'Equipamentos de Segurança, Emergência e Sinalização', 12, 'Possui faixas refletivas, afixadas na localização correta e íntegras?', true),
  ('onb13', 'vme-onibus-csp', 'base', 'Equipamentos de Segurança, Emergência e Sinalização', 13, 'Possui janelas de emergência e saídas de emergências? Estão sinalizadas?', true),
  ('onb14', 'vme-onibus-csp', 'base', 'Estrutura, Alertas e Ergonomia', 14, 'O banco do motorista possui regulagem?', true),
  ('onb15', 'vme-onibus-csp', 'base', 'Estrutura, Alertas e Ergonomia', 15, 'Possui para-choques dianteiro e traseiro em boas condições?', true),
  ('onb16', 'vme-onibus-csp', 'base', 'Estrutura, Alertas e Ergonomia', 16, 'Possui buzina audível?', true)
